//! The model's search over the real machine
//! (`design/installation-machine-2026-11-14.md`, section 8).
//!
//! The environment, the bounds and the eight checks are those of the
//! executable model, `design/installation-machine-model.py`; its step is
//! the Rust machine, built from a state of the model and read back into
//! one. The table the search finds is compared, line for line, with the
//! model's own output (`tests/model-table.txt`, generated by `python3 -I
//! design/installation-machine-model.py --table` and never edited).

extern crate std;

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet, VecDeque};
use std::string::{String, ToString};
use std::vec::Vec;
use std::{format, vec};

use super::*;
use oer_protocols_ieee80211_contracts_port::{
    ArenaState, RunPhase, StartFailure, StateSerial, StopCause,
};

/// The port's fault, as the search names it.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Fault;

/// The channel a run asks.
const CHANNEL: u8 = 6;
/// The instant of every step but a deadline's.
const NOW: Instant = Instant::from_micros(0);
/// Every request's deadline in the search that is compared with the
/// model's table: after any retry time of a step, the instant of the
/// model's `deadline`.
const DEADLINE: Instant = Instant::from_micros(1_000_000);
/// A deadline before the retry time of a step at [`NOW`].
const EARLY: Instant = Instant::from_micros(5);
/// The retry interval.
const RETRY: Duration = Duration::from_micros(10);

type M = Machine<'static, u8, Fault>;

/// A state of the model: `pos goal data tokens drain net wait`.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
struct S {
    pos: &'static str,
    goal: Option<&'static str>,
    data: &'static str,
    tokens: &'static str,
    drain: &'static str,
    net: Option<&'static str>,
    wait: Option<&'static str>,
}

fn outstanding(fault: Option<Fault>) -> Outstanding<Fault> {
    Outstanding {
        phase: RunPhase::Stopped,
        fault,
        received: 0,
        lent: 1,
        removals: 0,
        retained_groups: 0,
        transmit_out: 0,
        queued: [0; 4],
        running: 0,
        arenas: ArenaState::Returnable,
    }
}

fn unconfirmed() -> StopUnconfirmed<Fault> {
    StopUnconfirmed {
        cause: StopCause::Deadline,
        outstanding: outstanding(None),
    }
}

fn stopped() -> Stopped<'static> {
    Stopped::issue(StateSerial::FIRST)
}

fn run_of(s: &S) -> Run {
    Run {
        data: match s.data {
            "flowing" => Data::Flowing,
            "stopping" => Data::Stopping,
            _ => Data::Stopped,
        },
        tokens: match s.tokens {
            "held" => Tokens::Held,
            "asked" => Tokens::Asked,
            _ => Tokens::Ended,
        },
        drain: match s.drain {
            "owed" => Drain::Owed,
            _ => Drain::Done,
        },
    }
}

/// The machine in the model's state `s`, its request's deadline `deadline`.
fn build(s: &S, deadline: Option<Instant>) -> M {
    let run = run_of(s);
    let life = match s.pos {
        "stopped" => Life::Port {
            right: StopRight::issue(),
            at: At::Stopped(stopped(), run),
        },
        "starting" => Life::Port {
            right: StopRight::issue(),
            at: At::Starting(Starting::issue(StateSerial::FIRST), run, CHANNEL),
        },
        "running" => Life::Port {
            right: StopRight::issue(),
            at: At::Running(run.tokens),
        },
        "stopping" => Life::Port {
            right: StopRight::issue(),
            at: At::Stopping(run),
        },
        "retired" => Life::Port {
            right: StopRight::issue(),
            at: At::Retired(Retired::issue(StateSerial::FIRST)),
        },
        "releasing" => Life::Releasing,
        "released" => Life::Released,
        other => panic!("no position {other}"),
    };
    let want = |goal: &str| match goal {
        "run" => Want::Run(CHANNEL),
        "halt" => Want::Halt,
        "restart" => Want::Restart,
        "release_stays" => Want::Release(NetworkStep::Stays),
        "release_stops" => Want::Release(match s.net {
            Some("stopped") => NetworkStep::Stopped,
            _ => NetworkStep::Told,
        }),
        other => panic!("no goal {other}"),
    };
    Machine {
        life,
        goal: match s.goal {
            None => Goal::None,
            Some(goal) => Goal::Open {
                want: want(goal),
                deadline,
            },
        },
        waiting: match s.wait {
            None => Waiting::Nothing,
            Some("radio") => Waiting::Radio(unconfirmed()),
            Some("fault") => Waiting::Fault(FaultKept {
                fault: Fault,
                outstanding: outstanding(Some(Fault)),
            }),
            Some("cleanup") => Waiting::Cleanup(CleanupRefused::Unavailable(Fault)),
            Some("outstanding") => Waiting::Outstanding(outstanding(None)),
            Some(other) => panic!("no wait {other}"),
        },
        retry: RETRY,
    }
}

fn data_name(data: Data) -> &'static str {
    match data {
        Data::Flowing => "flowing",
        Data::Stopping => "stopping",
        Data::Stopped => "stopped",
    }
}

fn tokens_name(tokens: Tokens) -> &'static str {
    match tokens {
        Tokens::Held => "held",
        Tokens::Asked => "asked",
        Tokens::Ended => "ended",
    }
}

fn drain_name(drain: Drain) -> &'static str {
    match drain {
        Drain::Owed => "owed",
        Drain::Done => "done",
    }
}

/// The model's position of a port that holds an installation.
fn place_of(at: &At<'static, u8>) -> (&'static str, Run) {
    let pos = match at {
        At::Stopped(..) => "stopped",
        At::Starting(..) => "starting",
        At::Running(_) => "running",
        At::Stopping(_) => "stopping",
        At::Retired(_) => "retired",
    };
    (pos, at.facts())
}

/// The model's state of the machine.
fn project(m: &M) -> S {
    let place = match &m.life {
        Life::Port { at, .. } => place_of(at),
        Life::Releasing => ("releasing", DONE),
        Life::Released => ("released", DONE),
    };
    project_parts(place, &m.goal, &m.waiting)
}

/// The model's state of the view of a port that holds an installation.
fn project_port(port: &Port<'_, 'static, u8, Fault>) -> S {
    project_parts(place_of(port.at), port.goal, port.waiting)
}

fn project_parts((pos, run): (&'static str, Run), goal: &Goal<u8>, waiting: &Waiting<Fault>) -> S {
    let (goal, net) = match *goal {
        Goal::None => (None, None),
        Goal::Open { want, .. } => match want {
            Want::Run(_) => (Some("run"), None),
            Want::Halt => (Some("halt"), None),
            Want::Restart => (Some("restart"), None),
            Want::Release(NetworkStep::Stays) => (Some("release_stays"), None),
            Want::Release(NetworkStep::Told) => (Some("release_stops"), Some("told")),
            Want::Release(NetworkStep::Stopped) => (Some("release_stops"), Some("stopped")),
        },
    };
    S {
        pos,
        goal,
        data: data_name(run.data),
        tokens: tokens_name(run.tokens),
        drain: drain_name(run.drain),
        net,
        wait: match waiting.class() {
            Waited::Nothing => None,
            Waited::Radio => Some("radio"),
            Waited::Fault => Some("fault"),
            Waited::Cleanup => Some("cleanup"),
            Waited::Outstanding => Some("outstanding"),
        },
    }
}

/// One item of a step's trace.
#[derive(Clone, Debug)]
enum Item {
    Ask {
        name: &'static str,
        proof: Option<&'static str>,
        at: S,
    },
    Answer {
        name: &'static str,
        answer: &'static str,
    },
    Tell(&'static str),
    /// The end's name, and the class of the permit it returned.
    End(&'static str, Option<&'static str>),
    Report(String),
    Drop(&'static str),
}

/// The model's input: its kind, and a request's name.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct In {
    kind: &'static str,
    request: &'static str,
}

impl In {
    const fn of(kind: &'static str) -> Self {
        Self { kind, request: "" }
    }

    /// The model's `inp[-1]`.
    fn last(&self) -> &'static str {
        if self.kind == "request" {
            self.request
        } else {
            self.kind
        }
    }
}

fn live() -> Live<'static> {
    Live { brand: PhantomData }
}

fn permit_for(request: &str, held: Option<&str>) -> Permit<'static> {
    match (request, held) {
        ("run" | "halt", _) | (_, Some("live")) => Permit::Live(live()),
        _ => Permit::Spent(Spent { brand: PhantomData }),
    }
}

/// A retune's request, asked under a gate the controller closed.
fn retune(deadline: Option<Instant>) -> Request<'static, u8> {
    let future = core::pin::pin!(oer_protocols_radio_port::branded(
        async |mint: oer_protocols_radio_port::Mint<
            '_,
            oer_protocols_ieee80211_contracts_port::GatePool,
        >| {
            let (open, issuer) = mint.into_pools();
            let closed = issuer.close(open);
            Request::retune(live(), CHANNEL, &closed, deadline)
        }
    ));
    let mut cx = core::task::Context::from_waker(core::task::Waker::noop());
    match core::future::Future::poll(future, &mut cx) {
        core::task::Poll::Ready(request) => request,
        core::task::Poll::Pending => panic!("a gate's mint performs no async operation"),
    }
}

/// The Rust input of the model's, and the instant of its step: a run of a
/// running radio is a retune.
fn input(
    inp: In,
    pos: &str,
    permit: Option<&str>,
    deadline: Option<Instant>,
) -> (Input<'static, u8>, Instant) {
    match inp.kind {
        "request" => {
            let request = match inp.request {
                "run" if pos == "running" => retune(deadline),
                "run" => Request::run(live(), CHANNEL, deadline),
                "halt" => Request::halt(live(), deadline),
                "restart" => Request::restart(permit_for(inp.request, permit), deadline),
                "release_stays" => {
                    Request::release(permit_for(inp.request, permit), Network::Stays, deadline)
                }
                "release_stops" => {
                    Request::release(permit_for(inp.request, permit), Network::Stops, deadline)
                }
                other => panic!("no request {other}"),
            };
            (Input::Request(request), NOW)
        }
        "turn" => (Input::Turn, NOW),
        "deadline" => (Input::Turn, deadline.unwrap_or(DEADLINE)),
        "fault" => (Input::Fault, NOW),
        "tokens_ended" => (Input::TokensEnded(TokensEnded { brand: PhantomData }), NOW),
        "network_stopped" => (Input::NetworkStopped, NOW),
        other => panic!("no input {other}"),
    }
}

/// How a run of one step ended.
enum Ran {
    /// The state after the step, its trace, the model's name of its rest,
    /// the rest itself, the deadline of the request open after it and the
    /// step's instant.
    Done(S, Vec<Item>, &'static str, Rest, Option<Instant>, Instant),
    Need(&'static str),
}

fn end_name(ended: &Ended<'static, Fault>) -> &'static str {
    match ended {
        Ended::Request(Ok(End::Started), _) => "ok/started",
        Ended::Request(Ok(End::Halted), _) => "ok/halted",
        Ended::Request(Ok(End::Reinstalled), _) => "ok/reinstalled",
        Ended::Released => "ok/released",
        Ended::Request(
            Err(
                Unreached::StartRefused(_)
                | Unreached::StartUnstopped { .. }
                | Unreached::StartInterrupted,
            ),
            _,
        ) => "err/start_refused",
        Ended::Request(Err(Unreached::RestartRefused(_)), _) => "err/restart_refused",
        Ended::Request(Err(Unreached::Deadline(_)), _) => "err/deadline",
    }
}

fn held_name(waited: Waited) -> &'static str {
    match waited {
        Waited::Nothing => "held/None",
        Waited::Radio => "held/radio",
        Waited::Fault => "held/fault",
        Waited::Cleanup => "held/cleanup",
        Waited::Outstanding => "held/outstanding",
    }
}

/// Run one step of the machine in state `s` with the answers given: what it
/// did, or the ask it stops at.
fn run(
    s: &S,
    inp: In,
    permit: Option<&str>,
    answers: &[&'static str],
    deadline: Option<Instant>,
) -> Ran {
    let mut machine = build(s, deadline);
    let (rust, now) = input(inp, s.pos, permit, deadline);
    let mut trace = Vec::new();
    if (inp.kind == "fault" || inp.kind == "deadline") && s.pos == "starting" {
        trace.push(Item::Drop("starting"));
    }
    let mut feed = answers.iter().copied();
    let mut step = machine.step(rust, now);
    macro_rules! ask {
        ($name:expr, $proof:expr, $at:expr) => {{
            trace.push(Item::Ask {
                name: $name,
                proof: $proof,
                at: $at,
            });
            let Some(answer) = feed.next() else {
                return Ran::Need($name);
            };
            trace.push(Item::Answer {
                name: $name,
                answer,
            });
            answer
        }};
    }
    loop {
        step = match step {
            Step::Start(proof, _channel, resume) => {
                let kind = match proof {
                    StartProof::Stopped(_) => "stopped",
                    StartProof::Starting(_) => "starting",
                };
                let answer = ask!("start", Some(kind), project_port(&resume.port));
                resume.answer(match answer {
                    "started" => Ok(StartProgress::Started),
                    "pending" => Ok(StartProgress::Pending(Starting::issue(StateSerial::FIRST))),
                    "refused" => Err(StartRefused::Refused(stopped(), StartFailure::Device)),
                    "unstopped" => Err(StartRefused::Unstopped {
                        cause: StartFailure::Device,
                        stop: unconfirmed(),
                    }),
                    _ => Err(StartRefused::Stale(StaleProof { proof })),
                })
            }
            Step::Stop(resume) => {
                let answer = ask!("stop", None, project_port(&resume.port));
                match answer {
                    "ok" => resume.answer(Ok(stopped())),
                    "pending" => resume.pending(),
                    _ => resume.answer(Err(unconfirmed())),
                }
            }
            Step::StopData(resume) => {
                let answer = ask!("stop_data", None, project_port(&resume.port));
                resume.answer(match answer {
                    "stopped" => DataStop::Stopped,
                    _ => DataStop::Going,
                })
            }
            Step::Clean(proof, resume) => {
                let answer = ask!("clean", Some("&stopped"), project_port(&resume.port));
                resume.answer(
                    proof,
                    match answer {
                        "ok" => Ok(()),
                        "faulted" => Err(CleanupRefused::Faulted(Fault)),
                        "later" => Err(CleanupRefused::Unavailable(Fault)),
                        _ => Err(CleanupRefused::Stale),
                    },
                )
            }
            Step::Retire(proof, resume) => {
                let answer = ask!("retire", Some("stopped"), project_port(&resume.port));
                resume.answer(match answer {
                    "ok" => Ok(Retired::issue(StateSerial::FIRST)),
                    "refused" => Err(ProofRefused::Refused(proof, outstanding(None))),
                    "refused_fault" => Err(ProofRefused::Refused(proof, outstanding(Some(Fault)))),
                    _ => Err(ProofRefused::Stale(StaleProof { proof })),
                })
            }
            Step::Reinstall(proof, resume) => {
                let answer = ask!("reinstall", Some("retired"), project_port(&resume.port));
                match answer {
                    "ok" => {
                        let (ended, resume) = resume.installed(stopped());
                        trace.push(Item::End(end_name(&ended), returned(&ended)));
                        resume.go()
                    }
                    "refused" => {
                        resume.refused(ProofRefused::Refused(proof, ReinstallRefused::Epochs))
                    }
                    _ => resume.refused(ProofRefused::Stale(StaleProof { proof })),
                }
            }
            Step::Release(proof, right, releasing) => {
                let answer = ask!("release", Some("retired"), project(releasing.machine));
                releasing.answer(match answer {
                    "ok" => Ok(()),
                    _ => Err(ReleaseRefused { proof, right }),
                })
            }
            Step::Released(ended, rest) => {
                trace.push(Item::End(end_name(&ended), returned(&ended)));
                Step::Rest(rest)
            }
            Step::Recover(resume) => {
                let answer = ask!("recover", None, project_port(&resume.port));
                resume.answer(match answer {
                    "clear" => Ok(Recovered::Clear),
                    "recovered" => Ok(Recovered::TakenBack),
                    _ => Err(FaultKept {
                        fault: Fault,
                        outstanding: outstanding(Some(Fault)),
                    }),
                })
            }
            Step::Tell(tell, resume) => {
                trace.push(Item::Tell(match tell {
                    Tell::EndTokens(_) => "end_tokens",
                    Tell::StopNetwork => "stop_network",
                    Tell::DataFlows => "data_flows",
                }));
                resume.go()
            }
            Step::Ended(ended, resume) => {
                trace.push(Item::End(end_name(&ended), returned(&ended)));
                resume.go()
            }
            Step::Interrupted(resume) => {
                trace.push(Item::Report("interrupted".to_string()));
                resume.go()
            }
            Step::Held(resume) => {
                trace.push(Item::Report(
                    held_name(resume.waiting().class()).to_string(),
                ));
                resume.go()
            }
            Step::Rest(rest) => {
                let named = match rest {
                    Rest::Round => "round",
                    Rest::Wake(Some(at)) if Some(at) == now.checked_add(RETRY) => "timer",
                    Rest::Wake(_) => "wake",
                };
                let after = machine.goal.deadline();
                return Ran::Done(project(&machine), trace, named, rest, after, now);
            }
        };
    }
}

/// The class of the permit an end returned.
fn returned(ended: &Ended<'static, Fault>) -> Option<&'static str> {
    match ended {
        Ended::Request(_, Permit::Live(_)) => Some("live"),
        Ended::Request(_, Permit::Spent(_)) => Some("spent"),
        Ended::Released => None,
    }
}

/// The instant a rest the model names `named` must carry, after a step at
/// `now` that leaves a request open until `deadline`: a wake names the
/// deadline, a timer the earlier of the deadline and the retry time.
fn named_instant(named: &str, deadline: Option<Instant>, now: Instant) -> Rest {
    let retry = now.saturating_add(RETRY);
    match named {
        "round" => Rest::Round,
        "timer" => Rest::Wake(Some(deadline.map_or(retry, |deadline| deadline.min(retry)))),
        _ => Rest::Wake(deadline),
    }
}

fn answers_of(name: &str) -> &'static [&'static str] {
    match name {
        "start" => &["started", "pending", "refused", "unstopped", "stale"],
        "stop" => &["ok", "pending", "unconfirmed"],
        "stop_data" => &["stopped", "going"],
        "clean" => &["ok", "faulted", "later", "stale"],
        "retire" => &["ok", "refused", "refused_fault", "stale"],
        "reinstall" => &["ok", "refused", "stale"],
        "release" => &["ok", "stale"],
        "recover" => &["clear", "recovered", "kept"],
        other => panic!("no ask {other}"),
    }
}

fn refusal(name: &str, answer: &str) -> bool {
    matches!(
        (name, answer),
        ("start", "refused" | "unstopped" | "stale")
            | ("stop", "unconfirmed")
            | ("stop_data", "going")
            | ("clean", "faulted" | "later" | "stale")
            | ("retire", "refused" | "refused_fault" | "stale")
            | ("reinstall", "refused" | "stale")
            | ("release", "stale")
            | ("recover", "kept")
    )
}

fn gives(name: &str, answer: &str) -> Option<&'static str> {
    match (name, answer) {
        ("start", "pending") => Some("starting"),
        ("start", "refused")
        | ("stop", "ok")
        | ("retire", "refused" | "refused_fault")
        | ("reinstall", "ok") => Some("stopped"),
        ("retire", "ok") | ("reinstall", "refused") => Some("retired"),
        _ => None,
    }
}

fn wakes(name: &str, answer: &str) -> bool {
    matches!(
        (name, answer),
        ("start" | "stop", "pending") | ("stop_data", "going") | ("retire", "refused")
    )
}

fn holds(pos: &str) -> Option<&'static str> {
    match pos {
        "stopped" => Some("stopped"),
        "starting" => Some("starting"),
        "retired" => Some("retired"),
        _ => None,
    }
}

fn proof_at(proof: &str) -> &'static str {
    match proof {
        "starting" => "starting",
        "retired" => "retired",
        _ => "stopped",
    }
}

const RETIRES: [&str; 3] = ["restart", "release_stays", "release_stops"];
const LIVE: [&str; 5] = ["run", "halt", "restart", "release_stays", "release_stops"];

/// The class of the permit an end returns.
fn permit(s: &S) -> Option<&'static str> {
    if s.pos == "released" {
        None
    } else if s.pos == "retired" || s.tokens != "held" {
        Some("spent")
    } else {
        Some("live")
    }
}

fn allowed(permit: Option<&str>) -> &'static [&'static str] {
    match permit {
        Some("live") => &LIVE,
        Some("spent") => &RETIRES,
        _ => &[],
    }
}

type Budget = (u32, u32, u32, u32);

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct Env {
    s: S,
    budget: Budget,
    open: Option<&'static str>,
    /// The controller was told to end this installation's tokens and has
    /// not yet.
    tok: Order,
    /// The network was told to stop and has not yet said so.
    net: Order,
    /// The last rest named a turn.
    turn: Turn,
    permit: Option<&'static str>,
    /// The controller holds this installation's tokens.
    live: Held,
    /// A run left the drain unfinished.
    kept: Unfinished,
    /// The transmit gate as the controller holds it: closed from a retune
    /// it asks until that radio runs again. Under a closed gate the data
    /// plane publishes nothing, which lets the radio stop with the data
    /// flowing.
    gate: Gate,
}

/// The transmit gate as the controller holds it.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum Gate {
    Open,
    Closed,
}

/// An order of the machine to a party, not yet carried out.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum Order {
    None,
    Out,
}

/// Whether the last rest named a turn.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum Turn {
    Unnamed,
    Named,
}

/// Whether the controller holds the installation's tokens.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum Held {
    Ended,
    Held,
}

/// Whether a run left the drain unfinished.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum Unfinished {
    Finished,
    Unfinished,
}

/// Every way one step can go.
fn steps(env: &Env, inp: In, nref: u32) -> Vec<(S, Vec<Item>, &'static str, u32)> {
    let mut ways = Vec::new();
    let mut stack: Vec<(Vec<&'static str>, u32)> = vec![(Vec::new(), 0)];
    while let Some((answers, used)) = stack.pop() {
        match run(&env.s, inp, env.permit, &answers, Some(DEADLINE)) {
            Ran::Done(s, trace, rest, _, _, _) => ways.push((s, trace, rest, used)),
            Ran::Need(name) => {
                for &answer in answers_of(name) {
                    let cost = u32::from(refusal(name, answer));
                    if used + cost <= nref {
                        let mut next = answers.clone();
                        next.push(answer);
                        stack.push((next, used + cost));
                    }
                }
            }
        }
    }
    ways
}

fn inputs(env: &Env) -> Vec<(In, Budget)> {
    let (nreq, nfault, nlate, nref) = env.budget;
    let mut out = Vec::new();
    if env.turn == Turn::Named {
        out.push((In::of("turn"), env.budget));
    } else if nlate > 0 {
        out.push((In::of("turn"), (nreq, nfault, nlate - 1, nref)));
    }
    if env.open.is_none() && nreq > 0 {
        for &request in allowed(env.permit) {
            out.push((
                In {
                    kind: "request",
                    request,
                },
                (nreq - 1, nfault, nlate, nref),
            ));
        }
    }
    if nfault > 0 {
        out.push((In::of("fault"), (nreq, nfault - 1, nlate, nref)));
    }
    if env.tok == Order::Out {
        out.push((In::of("tokens_ended"), env.budget));
    } else if nlate > 0 && env.live == Held::Held {
        out.push((In::of("tokens_ended"), (nreq, nfault, nlate - 1, nref)));
    }
    if env.net == Order::Out {
        out.push((In::of("network_stopped"), env.budget));
    } else if nlate > 0 {
        out.push((In::of("network_stopped"), (nreq, nfault, nlate - 1, nref)));
    }
    if nlate > 0 && env.s.goal.is_some() {
        out.push((In::of("deadline"), (nreq, nfault, nlate - 1, nref)));
    }
    out
}

fn quiet(env: &Env) -> bool {
    let s = &env.s;
    if s.goal.is_some() || env.open.is_some() {
        return false;
    }
    s.pos == "released"
        || (s.data != "stopping" && matches!(s.pos, "stopped" | "running" | "retired"))
}

type Table = BTreeMap<
    (&'static str, &'static str, &'static str),
    BTreeSet<(Vec<&'static str>, &'static str, Vec<String>, &'static str)>,
>;

struct Search {
    seen: usize,
    machine_states: usize,
    problems: BTreeMap<&'static str, usize>,
    dead: usize,
    table: Table,
}

fn explore(budget: Budget) -> Search {
    let first = Env {
        s: S {
            pos: "stopped",
            goal: None,
            data: "stopped",
            tokens: "held",
            drain: "done",
            net: None,
            wait: None,
        },
        budget,
        open: None,
        tok: Order::None,
        net: Order::None,
        turn: Turn::Unnamed,
        permit: Some("live"),
        live: Held::Held,
        kept: Unfinished::Finished,
        gate: Gate::Open,
    };
    let mut seen = HashSet::from([first]);
    let mut queue = VecDeque::from([first]);
    let mut edges: HashMap<Env, Vec<Env>> = HashMap::new();
    let mut problems: BTreeMap<&'static str, usize> = BTreeMap::new();
    let mut problem = |kind: &'static str| *problems.entry(kind).or_default() += 1;
    let mut table: Table = BTreeMap::new();
    while let Some(env) = queue.pop_front() {
        let mut outs = Vec::new();
        for (inp, budget2) in inputs(&env) {
            let s = env.s;
            for (ns, trace, rest, used) in steps(&env, inp, budget2.3) {
                let (mut opened, mut tok, mut net, mut held_permit, mut live) = (
                    env.open,
                    env.tok == Order::Out,
                    env.net == Order::Out,
                    env.permit,
                    env.live == Held::Held,
                );
                let mut kept = env.kept == Unfinished::Unfinished;
                let mut gate = env.gate;
                if inp.kind == "request" && inp.request == "run" && s.pos == "running" {
                    // A retune is asked under a closed gate.
                    gate = Gate::Closed;
                }
                if inp.kind == "request" {
                    if opened.is_some() {
                        problem("two requests open");
                    }
                    if s.pos != "released" && !allowed(permit(&s)).contains(&inp.request) {
                        problem("a request the machine cannot serve");
                    }
                    opened = Some(inp.request);
                }
                if inp.kind == "tokens_ended" {
                    tok = false;
                    live = false;
                    if opened.is_none() && held_permit == Some("live") {
                        held_permit = Some("spent");
                    }
                }
                if inp.kind == "network_stopped" {
                    net = false;
                }
                let mut asked: Vec<&str> = Vec::new();
                let mut held = holds(s.pos);
                let (mut ends, mut moved, mut woken) = (0, false, false);
                let mut returned = None;
                for item in &trace {
                    match item {
                        Item::Ask { name, proof, at } => {
                            if asked.contains(name) {
                                problem("asked twice in a step");
                            }
                            asked.push(name);
                            if let Some(proof) = proof {
                                if held != Some(proof_at(proof)) {
                                    problem("ask without its proof");
                                }
                                if !proof.starts_with('&') {
                                    held = None;
                                    let out = if *name == "release" {
                                        "releasing"
                                    } else {
                                        "stopping"
                                    };
                                    if at.pos != out {
                                        problem("a proof is out and the state says it is held");
                                    }
                                }
                            }
                            if *name == "retire"
                                && !(at.data == "stopped"
                                    && at.tokens == "ended"
                                    && at.drain == "done")
                            {
                                problem("retire asked early");
                            }
                            if *name == "retire" && kept {
                                problem("retire asked with the drain unfinished");
                            }
                            if *name == "retire" && live {
                                problem("retire asked with the tokens out");
                            }
                            if *name == "release"
                                && at.goal == Some("release_stops")
                                && at.net != Some("stopped")
                            {
                                problem("release before the network stopped");
                            }
                            if *name == "start" && at.data == "stopping" {
                                problem("start while the data is stopping");
                            }
                            if *name == "stop" && at.data == "flowing" && gate != Gate::Closed {
                                problem(
                                    "the radio's stop asked with the data flowing and the gate open",
                                );
                            }
                        }
                        Item::Answer { name, answer } => {
                            if let Some(given) = gives(name, answer) {
                                held = Some(given);
                            }
                            if (*name, *answer) == ("clean", "ok") {
                                // The cleanup finished: the drain is done.
                                kept = false;
                            }
                            if (*name, *answer) == ("start", "started") {
                                kept = true;
                                // The radio runs: the controller opens the gate.
                                gate = Gate::Open;
                            }
                            if *answer == "stale" {
                                held = None;
                            }
                            if *answer == "stale" || (*name == "recover" && *answer != "kept") {
                                moved = true;
                            }
                            if wakes(name, answer) {
                                woken = true;
                            }
                            if (*name, *answer) == ("reinstall", "ok") {
                                tok = false;
                                live = true;
                            }
                        }
                        Item::Drop(proof) => {
                            if held != Some(*proof) {
                                problem("dropped a proof not held");
                            }
                            held = None;
                        }
                        Item::Tell(name) => {
                            if *name == "end_tokens" {
                                if tok {
                                    problem("the tokens' end told twice");
                                }
                                tok = true;
                            }
                            if *name == "stop_network" {
                                net = true;
                            }
                        }
                        Item::End(_, permit) => {
                            returned = *permit;
                            ends += 1;
                            if opened.is_none() {
                                problem("an end with no request");
                            }
                            opened = None;
                        }
                        Item::Report(_) => {}
                    }
                }
                if ends > 1 {
                    problem("two ends in a step");
                }
                if asked.len() > 7 {
                    problem("a step too long");
                }
                if holds(ns.pos) != held {
                    problem("proof not accounted");
                }
                // A release that is due is the next turn's: that round does
                // something whatever this input changed.
                let due = ns.pos == "retired"
                    && (ns.goal == Some("release_stays")
                        || (ns.goal == Some("release_stops") && ns.net == Some("stopped")));
                if rest == "round" && ns == s && !moved && ends == 0 && !due {
                    problem("a round with nothing changed");
                }
                if ns.goal.is_none() != opened.is_none() {
                    problem("goal and open request differ");
                }
                // The permit the controller holds is the one the machine
                // returned; it must be the class of the machine's state.
                if ends > 0 {
                    if returned != permit(&ns) {
                        problem("an end returned a permit of another class");
                    }
                    held_permit = returned;
                }
                if opened.is_none() && held_permit == Some("live") && !live {
                    problem("a live permit with the tokens ended");
                }
                let kinds: Vec<String> = trace
                    .iter()
                    .filter_map(|item| match item {
                        Item::Ask { name, .. } | Item::Tell(name) | Item::End(name, _) => {
                            Some((*name).to_string())
                        }
                        Item::Report(what) => Some(what.clone()),
                        Item::Answer { .. } | Item::Drop(_) => None,
                    })
                    .collect();
                let answers: Vec<&'static str> = trace
                    .iter()
                    .filter_map(|item| match item {
                        Item::Answer { answer, .. } => Some(*answer),
                        _ => None,
                    })
                    .collect();
                // The same way of the step with no deadline, one before the
                // retry time and one after it: every rest names its instant.
                for deadline in [None, Some(EARLY), Some(DEADLINE)] {
                    if deadline.is_none() && inp.kind == "deadline" {
                        continue;
                    }
                    match run(&s, inp, env.permit, &answers, deadline) {
                        Ran::Done(_, _, _, raw, after, now) => {
                            if raw != named_instant(rest, after, now) {
                                problem("a rest names the wrong instant");
                            }
                        }
                        Ran::Need(_) => problem("a way of a step changes with its deadline"),
                    }
                }
                table
                    .entry((s.pos, s.goal.unwrap_or("-"), inp.last()))
                    .or_default()
                    .insert((answers, ns.pos, kinds, rest));
                let next = Env {
                    s: ns,
                    budget: (budget2.0, budget2.1, budget2.2, budget2.3 - used),
                    open: opened,
                    tok: if tok { Order::Out } else { Order::None },
                    net: if net { Order::Out } else { Order::None },
                    turn: if rest != "wake"
                        || woken
                        || (inp.kind == "fault" && env.turn == Turn::Named)
                    {
                        Turn::Named
                    } else {
                        Turn::Unnamed
                    },
                    permit: held_permit,
                    live: if live { Held::Held } else { Held::Ended },
                    kept: if kept {
                        Unfinished::Unfinished
                    } else {
                        Unfinished::Finished
                    },
                    gate,
                };
                outs.push(next);
                if seen.insert(next) {
                    queue.push_back(next);
                }
            }
        }
        edges.insert(env, outs);
    }
    // A fault the port keeps with the radio stopped is the one state
    // nothing in the model ends.
    let rest_states: HashSet<Env> = seen
        .iter()
        .copied()
        .filter(|e| {
            quiet(e) || (e.s.wait == Some("fault") && matches!(e.s.pos, "stopped" | "retired"))
        })
        .collect();
    let mut back: HashMap<Env, Vec<Env>> = HashMap::new();
    for (a, outs) in &edges {
        for b in outs {
            back.entry(*b).or_default().push(*a);
        }
    }
    let mut good = rest_states.clone();
    let mut queue: VecDeque<Env> = rest_states.into_iter().collect();
    while let Some(b) = queue.pop_front() {
        for a in back.get(&b).into_iter().flatten() {
            if good.insert(*a) {
                queue.push_back(*a);
            }
        }
    }
    let dead = seen.iter().filter(|e| !good.contains(e)).count();
    let machine_states = seen.iter().map(|e| e.s).collect::<HashSet<_>>().len();
    Search {
        seen: seen.len(),
        machine_states,
        problems,
        dead,
        table,
    }
}

/// The search's output in the model's `--table` form.
fn printed(search: &Search) -> String {
    let ways: usize = search.table.values().map(BTreeSet::len).sum();
    let mut out = format!(
        "environment states visited: {}; machine states: {}; ways of a step: {}\n",
        search.seen, search.machine_states, ways
    );
    for (kind, count) in &search.problems {
        out.push_str(&format!("PROBLEM {kind}: {count}\n"));
    }
    out.push_str(&format!("dead ends: {}\n", search.dead));
    for ((pos, goal, inp), outs) in &search.table {
        for (answers, to, kinds, rest) in outs {
            let answers = if answers.is_empty() {
                "—".to_string()
            } else {
                answers.join(", ")
            };
            let kinds = if kinds.is_empty() {
                "—".to_string()
            } else {
                kinds.join(", ")
            };
            out.push_str(&format!(
                "| {pos} | {goal} | {inp} | {answers} | {to} | {kinds} | {rest} |\n"
            ));
        }
    }
    out
}

#[test]
fn the_search_over_the_machine_finds_the_models_table() {
    let search = explore((3, 1, 1, 2));
    assert!(search.problems.is_empty(), "{:?}", search.problems);
    assert_eq!(search.dead, 0, "dead ends");
    // A step asks at most five things: the most answers one way of a step
    // takes.
    let asks = search
        .table
        .values()
        .flatten()
        .map(|(answers, ..)| answers.len())
        .max();
    assert_eq!(asks, Some(5), "the most asks of a step");
    let expected = include_str!("../tests/model-table.txt");
    let found = printed(&search);
    for (line, (found, expected)) in found.lines().zip(expected.lines()).enumerate() {
        assert_eq!(found, expected, "line {}", line + 1);
    }
    assert_eq!(
        found.lines().count(),
        expected.lines().count(),
        "the table's length"
    );
}

#[test]
fn the_search_holds_at_the_models_wider_bounds() {
    // The ways of a step the model finds at each bound
    // (`python3 -I design/installation-machine-model.py <bound>`).
    for (budget, model_ways) in [
        ((3, 1, 1, 3), 2_029),
        ((4, 2, 2, 3), 2_111),
        ((3, 2, 3, 4), 2_247),
    ] {
        let search = explore(budget);
        assert!(
            search.problems.is_empty(),
            "{budget:?}: {:?}",
            search.problems
        );
        assert_eq!(search.dead, 0, "{budget:?}: dead ends");
        let ways: usize = search.table.values().map(BTreeSet::len).sum();
        assert_eq!(ways, model_ways, "{budget:?}: the ways of a step");
    }
}

#[test]
fn a_placed_machine_halts_a_stopped_radio_at_once_and_returns_a_live_permit() {
    let mut place = MaybeUninit::uninit();
    let (machine, permit) = M::place(&mut place, stopped(), StopRight::issue(), RETRY);
    let step = machine.step(Input::Request(Request::halt(permit, None)), NOW);
    let Step::Ended(Ended::Request(Ok(End::Halted), Permit::Live(_)), resume) = step else {
        panic!("a stopped radio with its data home halts at once");
    };
    assert!(matches!(resume.go(), Step::Rest(Rest::Wake(None))));
}

/// A retune's request keeps its deadline: the radio's stop that does not
/// confirm at once rests until that deadline, as a run's would.
#[test]
fn a_retune_rests_until_its_deadline_while_the_radio_stops() {
    let running = S {
        pos: "running",
        goal: None,
        data: "flowing",
        tokens: "held",
        drain: "owed",
        net: None,
        wait: None,
    };
    let mut machine = build(&running, None);
    let Step::Stop(resume) = machine.step(Input::Request(retune(Some(DEADLINE))), NOW) else {
        panic!("a retune stops the running radio, the data flowing under the closed gate");
    };
    assert!(matches!(
        resume.pending(),
        Step::Rest(Rest::Wake(Some(deadline))) if deadline == DEADLINE
    ));
}
